import React, { useState, useEffect } from "react";
import { View, FlatList } from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Nota } from "./Nota";
import NotaEditor from "./NotaEditor";

export default function App() {
  const [notas, setNotas] = useState([]);

  const mostraNotas = async () => {
    try {
      const todasChaves = await AsyncStorage.getAllKeys();
      const todasNotas = await AsyncStorage.multiGet(todasChaves);

      console.log("Notas carregadas:", todasNotas);

      // Filtra notas vazias
      const notasFiltradas = todasNotas.filter(([chave, valor]) => 
        valor && valor.trim() !== ""
      );

      setNotas(notasFiltradas);
    } catch (error) {
      console.error("Erro ao carregar notas:", error);
    }
  };

  useEffect(() => {
    mostraNotas();
  }, []);

  return (
    <View style={{ flex: 1 }}>
      <FlatList
        data={notas}
        keyExtractor={(item) => item[0]} // Usa a chave como id
        renderItem={({ item }) => <Nota item={item} />}
        ListEmptyComponent={
          <Text style={{ textAlign: "center", marginTop: 20, padding: 16 }}>
            Nenhuma nota encontrada. Clique no + para criar uma nova nota.
          </Text>
        }
      />
      <NotaEditor mostraNotas={mostraNotas} />
    </View>
  );
}
